UNITS = {"s": 1, "m": 60, "h": 3600}


def parse_duration(text):
    total = 0
    num = ""
    for ch in text:
        if ch.isdigit():
            num += ch
        else:
            total += int(num) * UNITS[ch]
            num = ""
    return total


def format_duration(seconds):
    h = seconds // 3600
    m = (seconds % 3600) // 60
    s = seconds % 60
    return "%dh%dm%ds" % (h, m, s)

