import time


def retry(times=3, exceptions=(ConnectionError, TimeoutError), delay=0):
    def deco(fn):
        def wrapper(*args, **kwargs):
            last = None
            for i in range(times):
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    last = e
                    time.sleep(delay)
            raise last
        return wrapper
    return deco

